150| \section{稳态近似}
151| 
152| \begin{theorem}[连续一级反应]\label{thm:b1:elementary-steps:consecutive}
153| 对于 $\mathrm{A} \xrightarrow{k_1} \mathrm{B} \xrightarrow{k_2} \mathrm{C}$，两步均为一级，且 $t = 0$ 时 $[\mathrm{A}] = a_0$，$[\mathrm{B}] =
154| [\mathrm{C}] = 0$，$k_1 \ne k_2$：
155| \[
156|   [\mathrm{A}] = a_0\eu^{-k_1t}, \qquad
157|   [\mathrm{B}] = \frac{a_0k_1}{k_2 - k_1}\big(\eu^{-k_1t} - \eu^{-k_2t}\big),
158|   \qquad [\mathrm{C}] = a_0 - [\mathrm{A}] - [\mathrm{B}] .
159| \]
160| 中间体在 $t_{\max} = \dfrac{\ln(k_2/k_1)}
161| {k_2 - k_1}$ 时达到极大值。
162| \end{theorem}
163| 
164| \begin{proof}
165| 由 $\dd[\mathrm{A}]/\dd t = -k_1[\mathrm{A}]$ 得 $[\mathrm{A}]$。再由
166| $\dd[\mathrm{B}]/\dd t + k_2[\mathrm{B}] = k_1a_0\eu^{-k_1t}$，这是一阶线性方程：两边乘以 $\eu^{k_2t}$，得 $\frac{\dd}{\dd t}
167| \big([\mathrm{B}]\eu^{k_2t}\big) = k_1a_0\eu^{(k_2-k_1)t}$，从 0 积分（此时 $[\mathrm{B}] = 0$）得 $[\mathrm{B}]\eu^{k_2t} =
168| \frac{k_1a_0}{k_2-k_1}(\eu^{(k_2-k_1)t} - 1)$。由物质守恒得 $[\mathrm{C}]$。当 $k_1\eu^{-k_1t}
169| = k_2\eu^{-k_2t}$，即 $t_{\max}$ 时，$[\mathrm{B}]$ 的导数为零。
170| \end{proof}
171| 
172| \begin{definition}[稳态近似]\label{def:b1:elementary-steps:qssa}
173| 在\emph{稳态近似}\index{稳态近似}（或准稳态）中，一种反应性很强、消耗速度远快于生成速度的中间体，在经过短暂的诱导期后，其浓度被视为恒定且很小：其生成速率等于消耗速率，
174| $\dd[\mathrm{I}]/\dd t \approx 0$。
175| \end{definition}
176| 
177| \begin{proposition}[稳态成立的条件]\label{prop:b1:elementary-steps:qssa-justified}
178| 对于 $\mathrm{A} \to \mathrm{B} \to \mathrm{C}$，若 $k_2 \gg k_1$：经过约 $1/k_2$ 量级的时间后，$[\mathrm{B}] \approx k_1[\mathrm{A}]/k_2$（这正是 $\dd[\mathrm{B}]/\dd t = 0$ 所给出的结果），$[\mathrm{B}]$ 保持很小，生成物以 $\dd[\mathrm{C}]/\dd t \approx k_1[\mathrm{A}]$ 的速率生成：第一步为决速步。
179| \end{proposition}
180| 
181| \begin{proof}
182| 当 $k_2 \gg k_1$ 且 $t \gg 1/k_2$ 时，$\eu^{-k_2t}$ 与 $\eu^{-k_1t}$ 相比可以忽略，且 $k_2 - k_1 \approx k_2$，故 $[\mathrm{B}] \approx (a_0k_1/k_2)
183| \eu^{-k_1t} = k_1[\mathrm{A}]/k_2 \ll [\mathrm{A}]$。于是
184| $\dd[\mathrm{C}]/\dd t = k_2[\mathrm{B}] \approx k_1[\mathrm{A}]$。
185| \end{proof}
